CREATE TEMPORARY VIEW image_search_main_aggregated_${grass_region_without_quote} AS
SELECT
    count(
        DISTINCT
        if(
            image_search_button_click_cnt > 0,
            user_id,
            NULL
        )
    ) AS camera_uu,
    count(
        DISTINCT
        if(
            image_search_pv > 0,
            user_id,
            NULL
        )
    ) AS dau,
    count(
        DISTINCT
        if(
            image_search_pv > 0
            AND search_entrance IN (
                'SEARCH_RESULT',
                'HOME',
                'Home',
                'MALL',
                'PRESEARCH',
                'NSRP',
                'RCMD_SEARCH_RESULT'
            ),
            user_id,
            NULL
        )
    ) AS landing_rate_dau,
    sum(
        image_search_item_imp_cnt
    ) AS imp_cnt,
    sum(
        pdp_pv
    ) AS ppv_cnt,
    sum(
        cart_cnt
    ) AS cart_cnt,
    sum(
        order_cnt
    ) AS order_cnt,
    sum(
        gmv
    ) AS gmv,
    count(
        DISTINCT
        if(
            image_search_item_imp_cnt > 0,
            user_id,
            NULL
        )
    ) AS imp_uu,
    count(
        DISTINCT
        if(
            pdp_pv > 0,
            user_id,
            NULL
        )
    ) AS ppv_uu,
    count(
        DISTINCT
        if(
            cart_cnt > 0,
            user_id,
            NULL
        )
    ) AS cart_uu,
    count(
        DISTINCT
        if(
            order_cnt > 0,
            user_id,
            NULL
        )
    ) AS order_uu,
    count(
        DISTINCT
        if(
            image_search_item_click_cnt > 0
            OR pdp_like_button_click_cnt > 0
            OR cart_cnt > 0,
            user_id,
            NULL
        )
    ) AS eff_trans_uu,
    sum(top1_similarity_sum) / sum(top1_item_impression_cnt) AS avg_top1_similarity,
    sum(click_location_sum) / sum(image_search_item_click_cnt) AS avg_click_location,
    sum(atc_location_sum) / sum(cart_cnt) AS avg_cart_location,
    sum(image_search_result_volume) AS image_search_result_volume,
    sum(image_search_non_result_volume) AS image_search_non_result_volume,
    sum(query_cnt) AS query_cnt
    ,is_ads
FROM
    srdi_mart.dws_sr_data_warehouse_image_search_entrance_user_metrics_1d
WHERE
    local_date = ${local_date}
    AND grass_region = ${grass_region}
GROUP BY GROUPING SETS (
    (is_ads), ()
)
;

