INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_image_search_main_dashboard_1d
PARTITION (
    grass_region = ${grass_region},
    local_date = ${local_date}
)
SELECT
    '__ALL__'  as platform
    ,camera_uu
    ,dau
    ,landing_rate_dau
    ,imp_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,imp_uu
    ,ppv_uu
    ,cart_uu
    ,order_uu
    ,eff_trans_uu
    ,avg_top1_similarity
    ,avg_click_location
    ,avg_cart_location
    ,image_search_result_volume
    ,image_search_non_result_volume
    ,query_cnt
    ,case
        when is_ads = true then 'true'
        when is_ads = false then 'false'
        else '__ALL__'
        end as is_ads
FROM
    image_search_main_aggregated_${grass_region_without_quote};
